            if (self._noticeOutsideToken !== token || !self._noticePanelsOpen) return;
            const t = e && e.target;
            if (t && t.closest && (t.closest('.bible-proj-notice-manage') ||
                t.closest('.bible-proj-notice-zone'))) return;
